const out={};
let total=0;
for (const p of ["dplyr","tidyr","ggplot2"]) {
  page.goto("https://cran.r-project.org/web/packages/"+p+"/index.html");
  const t = page.evaluate(() => { const tds=[...document.querySelectorAll("tr")].find(r=>r.children[0]&&r.children[0].textContent.trim()==="Imports:"); return tds?tds.children[1].textContent:""; });
  const n = t.split(",").map(s=>s.trim()).filter(Boolean).length;
  out[p]=[n,t]; total+=n;
}
out.total=total;
return out;
